    for(const line of raw.split(/\r?\n/)){const match=line.match(/^\s*([A-Za-z#]+)\s*:\s*(.*?)\s*$/);if(!match)continue;const rawKey=match[1],key=rawKey.toLowerCase(),value=match[2].trim();
      if(['algorithm','alg','scramble','moves'].includes(key))config.algorithm=value;else if(key==='solution')config.solution=value;else if(key==='case'||key==='mode')config.caseType=value.toLowerCase();else if(key==='setup')config.setup=value.toLowerCase();else if(key==='facelets'&&/^[URFDLB]{54}$/i.test(value))config.facelets=value.toUpperCase();else if(key==='speed')config.speed=THREE.MathUtils.clamp(Number(value)||.42,.12,1.5);else if(key==='autoplay')config.autoplay=!/^(false|no|0)$/i.test(value);else if(/^[urfdlb]$/.test(key)&&value){if(/^[URFDLB]{9}$/i.test(value))faces[key.toUpperCase()]=value.toUpperCase();else if(/^#?[0-9a-f]{6}$/i.test(value)){const face=key.toUpperCase();config.colors[face]=parseInt(value.replace('#',''),16);explicitColors.add(face);}}else if(/^color[urfdlb]$/.test(key)&&/^#?[0-9a-f]{6}$/i.test(value)){const face=key.at(-1).toUpperCase();config.colors[face]=parseInt(value.replace('#',''),16);explicitColors.add(face);}else if(/^(URF|UFL|ULB|UBR|DFR|DLF|DBL|DRB)$/i.test(rawKey)&&/^[URFDLB]{3}$/i.test(value))config[rawKey.toUpperCase()]=value.toUpperCase();}
